import{_ as a,o as s,c as n,a2 as d}from"./chunks/framework.B4hAkGey.js";const g=JSON.parse('{"title":"6.1 基础入门：5G URLLC / eMBB / mMTC","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-5g-adaptation/basics.md","filePath":"guide/06-5g-adaptation/basics.md","lastUpdated":1792683941000}'),e={name:"guide/06-5g-adaptation/basics.md"};function r(o,t,p,i,l,h){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="_6-1-基础入门-5g-urllc-embb-mmtc" tabindex="-1">6.1 基础入门：5G URLLC / eMBB / mMTC <a class="header-anchor" href="#_6-1-基础入门-5g-urllc-embb-mmtc" aria-label="Permalink to &quot;6.1 基础入门：5G URLLC / eMBB / mMTC&quot;">​</a></h1><blockquote><p>5G 三大场景如何重塑 WebRTC 实时互动直播的技术选型与部署架构。</p></blockquote><hr><h2 id="_6-1-1-5g-三大场景速览" tabindex="-1">6.1.1 5G 三大场景速览 <a class="header-anchor" href="#_6-1-1-5g-三大场景速览" aria-label="Permalink to &quot;6.1.1 5G 三大场景速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>全称</th><th>核心 KPI</th><th>WebRTC 适配</th></tr></thead><tbody><tr><td><strong>eMBB</strong></td><td>Enhanced Mobile Broadband</td><td>峰值 20Gbps / 用户 100Mbps</td><td>4K/8K 直播成为常规；上行 10Gbps 峰值让手机也能推 4K</td></tr><tr><td><strong>URLLC</strong></td><td>Ultra-Reliable Low Latency Communications</td><td>端到端 ≤ 1ms / 可靠性 ≥ 99.999%</td><td>空口时延从 4G 的 30~50ms 降到 1~10ms</td></tr><tr><td><strong>mMTC</strong></td><td>Massive Machine-Type Communications</td><td>百万连接/km²</td><td>IoT 监控设备接入 WebRTC 成本骤降</td></tr></tbody></table><p>WebRTC 实时互动直播主要受益于 <strong>eMBB + URLLC</strong> 的<strong>组合拳</strong>。</p><hr><h2 id="_6-1-2-5g-vs-4g-实测数据-来源-itu-gsma-运营商公开报告" tabindex="-1">6.1.2 5G vs 4G 实测数据（来源：ITU / GSMA / 运营商公开报告） <a class="header-anchor" href="#_6-1-2-5g-vs-4g-实测数据-来源-itu-gsma-运营商公开报告" aria-label="Permalink to &quot;6.1.2 5G vs 4G 实测数据（来源：ITU / GSMA / 运营商公开报告）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>4G LTE CAT18</th><th>5G SA n77/n78</th><th>改善倍率</th></tr></thead><tbody><tr><td>空口单向时延</td><td>30~50ms</td><td><strong>1~10ms</strong></td><td>5~30×</td></tr><tr><td>端到端时延</td><td>150~300ms</td><td><strong>50~120ms</strong></td><td>2~3×</td></tr><tr><td>下行峰值</td><td>1.2Gbps</td><td><strong>20Gbps</strong></td><td>17×</td></tr><tr><td>上行峰值</td><td>500Mbps</td><td><strong>10Gbps</strong></td><td>20×</td></tr><tr><td>上行 MIMO</td><td>2×2</td><td><strong>4×4 / 8×8</strong></td><td>2~4×</td></tr><tr><td>移动性切换时延</td><td>200ms</td><td><strong>&lt; 20ms</strong></td><td>10×</td></tr><tr><td>面间（切片）隔离</td><td>不支持</td><td><strong>原生支持</strong></td><td>—</td></tr><tr><td>网络能量效率</td><td>基线</td><td><strong>提升 100×</strong></td><td>100×</td></tr></tbody></table><hr><h2 id="_6-1-3-5g-网络切片-network-slicing" tabindex="-1">6.1.3 5G 网络切片（Network Slicing） <a class="header-anchor" href="#_6-1-3-5g-网络切片-network-slicing" aria-label="Permalink to &quot;6.1.3 5G 网络切片（Network Slicing）&quot;">​</a></h2><p>运营商可以把一张物理 5G 网络切成多张<strong>逻辑独立的虚拟网络</strong>，每张有独立的 SLA。WebRTC 直播可以申请一张专属切片：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 物理 5G 网络                      │</span></span>
<span class="line"><span>├──────────┬──────────┬──────────┬─────────────────┤</span></span>
<span class="line"><span>│ 切片 A   │ 切片 B   │ 切片 C   │ 切片 D          │</span></span>
<span class="line"><span>│ WebRTC   │ IoT      │ 自动驾驶 │ 普通移动宽带      │</span></span>
<span class="line"><span>│ 直播     │          │          │                  │</span></span>
<span class="line"><span>│ QFI=101  │ QFI=102  │ QFI=103  │ QFI=104         │</span></span>
<span class="line"><span>│ 高优先级 │ 低功耗   │ 极低时延 │ 大带宽          │</span></span>
<span class="line"><span>└──────────┴──────────┴──────────┴─────────────────┘</span></span></code></pre></div><p>客户端通过 <strong>5G QoS Flow Identifier (QFI)</strong> 标识自己在哪个切片里。WebRTC 可以据此做差异化调度。</p><hr><h2 id="_6-1-4-移动边缘计算-mec" tabindex="-1">6.1.4 移动边缘计算（MEC） <a class="header-anchor" href="#_6-1-4-移动边缘计算-mec" aria-label="Permalink to &quot;6.1.4 移动边缘计算（MEC）&quot;">​</a></h2><p>5G 把计算和 CDN 节点<strong>下沉到基站侧</strong>（通常距离终端 1~2 跳）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统 WebRTC 直播：</span></span>
<span class="line"><span>手机 → 基站 → 核心网 → 骨干网 → 中心机房 SFU → 骨干网 → ... → 观众</span></span>
<span class="line"><span>                                                  ↑ 延迟 50~100ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5G MEC 架构：</span></span>
<span class="line"><span>手机 → 基站 → 边缘 SFU（就在基站机房） → 边缘 CDN → ... → 观众</span></span>
<span class="line"><span>                  ↑ 减少 3~5 跳，省 50~100ms</span></span></code></pre></div><p>MEC 还能做：</p><ul><li>边缘转码（主播推一路，边缘实时转多路给不同带宽观众）</li><li>边缘录制（省中心机房存储）</li><li>边缘 AI（美颜、背景分割实时跑在边缘 GPU 上）</li></ul><hr><h2 id="_6-1-5-小结" tabindex="-1">6.1.5 小结 <a class="header-anchor" href="#_6-1-5-小结" aria-label="Permalink to &quot;6.1.5 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th></tr></thead><tbody><tr><td><strong>eMBB</strong></td><td>大带宽让 4K/60fps 直播成为手机标配</td></tr><tr><td><strong>URLLC</strong></td><td>1ms 空口时延是直播互动的基石</td></tr><tr><td><strong>切片</strong></td><td>运营商为 WebRTC 开辟 QoS 保障通道</td></tr><tr><td><strong>MEC</strong></td><td>SFU/转码/AI 下沉到基站，省延迟</td></tr><tr><td><strong>5G CGN</strong></td><td>运营商级 NAT 仍然存在，TURN 不能少</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./advanced">6.2 进阶应用：5G 切片与 QoS 保障</a></p>`,26)])])}const b=a(e,[["render",r]]);export{g as __pageData,b as default};
